static int field_source_index(const FieldDef *d){(void)d;return 0;}
/* Fixed HMI slot assignments captured on 15 Oct 2026. Read IDs again before every write. */
static int field_identity(int i,int *expected){
 if(i==F_HEAT1_SET||i==F_HEAT1_ON||i==F_HEAT1_ACTUAL){*expected=1;return F_HEAT1_ID;}
 if(i==F_HEAT2_SET||i==F_HEAT2_ON||i==F_HEAT2_ACTUAL){*expected=2;return F_HEAT2_ID;}
 if(i==F_HEAT3_SET||i==F_HEAT3_ON||i==F_HEAT3_ACTUAL){*expected=3;return F_HEAT3_ID;}
 if(i==F_HEAT4_SET||i==F_HEAT4_ON||i==F_HEAT4_ACTUAL){*expected=5;return F_HEAT4_ID;}
 if(i==F_HEAT5_SET||i==F_HEAT5_ON||i==F_HEAT5_ACTUAL){*expected=9;return F_HEAT5_ID;}
 if(i==F_HEAT6_SET||i==F_HEAT6_ON){*expected=21;return F_HEAT6_ID;}
 if(i==F_SUPPORT1_TIME||i==F_SUPPORT1_ENABLED){*expected=1;return F_SUPPORT1_IDENTITY;}
 if(i==F_SUPPORT2_TIME||i==F_SUPPORT2_ENABLED){*expected=2;return F_SUPPORT2_IDENTITY;}
 if(i==F_DRILL1_TIME||i==F_DRILL1_ENABLED){*expected=7;return F_DRILL1_IDENTITY;}
 if(i==F_VIDEOJET1_TIME||i==F_VIDEOJET1_ENABLED){*expected=10;return F_VIDEOJET1_IDENTITY;}
 if(i==F_HANDLE1_TIME||i==F_HANDLE1_ENABLED){*expected=4;return F_HANDLE1_IDENTITY;}
 return -1;
}
static int field_virtual(int i){return i==F_DANCER1||i==F_DANCER2;}
static int field_configuration(int i){switch(i){case F_CFG_CENE_SERVO_VAR:case F_CFG_ELGECME_SERVO_VAR:case F_CFG_TUTUCU_SERVO_VAR:case F_EQUIP_GLUE:case F_EQUIP_LINER:case F_CFG_SARICI_VAR:case F_CFG_DELIK_ENC_UNITE_VAR:case F_CFG_BALERIN2_POTANS_CALISMA_AKTIF:case F_CFG_POTANSLI_CALISMA_AKTIF:case F_CFG_SISTEMDE_EMNIYET_P_L_C_VAR:case F_CFG_EMNIYET_P_L_C__MODULLU_VERSIYON:case F_CFG_EMNIYET_KAPILAR_PASIF:case F_CFG_EMNIYET_KAPI_V_A_R:case F_CFG_EMNIYET_BARIYER_V_A_R:case F_CFG_YOLUNA_KAYNAK_VAR1:case F_CFG_YOLUNA_KAYNAK_VAR2:case F_CFG_EK_KART_UNITE_VAR:case F_CFG_CIFT_CENE_UNITE:case F_CFG_SONIC_UNITE_VAR:case F_UNWINDER_SENSOR:case F_CFG_DILIMLEME_UNITE_VAR:case F_CFG_LOAD_CELL_UNITE_VAR:case F_CFG_LOADCEL_MODUL_VAR:case F_CFG_ACICI_CAP_SENSOR_AKTIF:case F_CFG_YUMUSAK_SAP_UNITE_VAR_YOK:case F_EQUIP_EJECT_AC:case F_CFG_ZIP_YOLUNA_KAYNAK_UNITE_VAR_YOK:case F_CFG_KATLAMA_UNITE_OPSIYON:case F_CFG_KATLAMA_E_K1100:case F_CFG_TAKVIYE_VAR:case F_CFG_EK_KAYNAK_SERVO_VAR:case F_CFG_TAVUK_FIRE_UNITE:case F_EQUIP_TAKEOFF:case F_CFG_TAKVIYE_HAT_CEKICI_UNITE:case F_CFG_SENKRON_MERDANE2_VAR:case F_CFG_SENKRON_MERDANE3_VAR:case F_CFG_HOTMELT2_UNITE_VAR:case F_CFG_INCH_MODE:case F_CFG_EL_GECME2_SERVO_VAR:case F_EQUIP_EJECT_JOG:case F_CFG_HOTMELT3_UNITE_VAR:case F_CFG_HOTMELT_SW_KONTROL:case F_EQUIP_HEAT:case F_CFG_SICAKLIK_ALARM_STOP_YAPSIN:case F_CFG_ZIPPER_UNITE_VAR:case F_CFG_TEFLON_UNITE_VAR:case F_CFG_ISTIFLEME_PISTONU_Y_O_K:case F_CFG_KORUK_UNITE_VAR:case F_CFG_SERVO_YUMUSAK_SAP_UNITE_VAR_YOK:case F_CFG_URUN_TOPLAMA_VAR:case F_CFG_YOLUNA_KAYNAK_BLOWER_VAR:case F_CFG_O_P_C_ACTIVE:case F_CFG_ACIC2_UNITE_VAR:case F_CFG_SEDEF_TAKMA_VAR_YOK:case F_CFG_KARGO_MAKINASI:case F_CFG_AKIM_ALARM_STOP_YAPSIN:case F_CFG_INJET_UNITE_VAR:case F_CFG_MERKEZ_PANO_STOP_SINYALI_VAR:case F_CFG_KARGO_PANO_STOP_SINYALI_VAR:case F_CFG_HOTMELT_ENCODER_MODULU_VAR:case F_CFG_CURRENT_ALARM_DELAY:case F_CFG_GLUE_ENCODER_PULSES:return 1;default:return 0;}}
enum { F_ENGINEERING_FIRST=256 };
static int field_engineer(int i){return i>=F_ENGINEERING_FIRST||i==F_HEAT6_ID||i==F_HEAT5_ID||i==F_HEAT4_ID||i==F_HEAT3_ID||i==F_HEAT2_ID||i==F_HEAT1_ID||i==F_HEAT5_LIMIT||i==F_HEAT4_LIMIT||i==F_HEAT3_LIMIT||i==F_HEAT2_LIMIT||i==F_HEAT1_LIMIT||i==F_HEAT6_LIMIT||i==F_HANDLE1_IDENTITY||i==F_VIDEOJET1_IDENTITY||i==F_DRILL1_IDENTITY||i==F_SUPPORT2_IDENTITY||i==F_SUPPORT1_IDENTITY||i==F_EDGE_COUNT||i==F_OFFSET_STEP||i==F_FEED_START||i==F_FEED_STOP||(i>=F_PERF_DUAL_FEED_START&&i<=F_PERF_LOW_MATERIAL_TIME)||field_configuration(i)||(i>=F_JAW_OFFSET&&i<=F_JAW_TRAFO)||i==F_CMD_KNIFE_SAVE;}
static int field_stopped(int i){(void)i;return 0;}
static int field_presence(int i,int *low,int *high){
 if(i==F_EDGE_SENSITIVITY){*low=1;*high=4;return F_EDGE_COUNT;}
 for(int n=0;n<3;n++)if(i==F_EDGE1_AUTO+2*n||i==F_EDGE1_REVERSE+2*n||i==F_EDGE1_POSITION+n||i==F_CMD_EDGE1_FW+2*n||i==F_CMD_EDGE1_BW+2*n){*low=n+1;*high=4;return F_EDGE_COUNT;}
 if(i==F_UNWINDER_STOP){*low=1;*high=1;return F_UNWINDER_SENSOR;}
 return -1;
}
/* The original fixed three-channel HMI permits a zero count. It does not
   mean that every edge-control signal is absent. Positive counts select the
   configurable page; unknown/out-of-range values still block the binding. */
static int field_presence_matches(int field,double value,int low,int high){return (field==F_EDGE_COUNT&&value==0)||(value>=low&&value<=high);}
static int field_lower_limit(int i){return i==F_WIDTH?F_WIDTH_MIN:i==F_WAIT?F_WAIT_MIN:-1;}
static int field_upper_limit(int i){
 if(i==F_WIDTH)return F_WIDTH_MAX;
 if(i==F_WELD)return F_WELD_LIMIT;
 if(i==F_SPEED)return F_SPEED_LIMIT;
 if(i==F_WAIT)return F_WAIT_LIMIT;
 const int sets[]={F_HEAT1_SET,F_HEAT2_SET,F_HEAT3_SET,F_HEAT4_SET,F_HEAT5_SET,F_HEAT6_SET};for(int n=0;n<6;n++)if(i==sets[n])return F_HEAT1_LIMIT+n;
 return -1;
}
static int field_width_limited(int i){return i==F_GLUE_START_OFFSET||i==F_GLUE_WORKING_DISTANCE||i==F_GLUE_WITHOUT_DISTANCE||i==F_PHOTO_SEARCH_WINDOW||i==F_PHOTO_OFFSET_TENTHS;}
static const char *type_name(FieldType t){static const char *names[]={"BOOL","INT","DINT","REAL","LREAL","TIME","STRING(12)"};return names[t];}
static int field_index(const char *key){for(int i=0;i<F_COUNT;i++)if(!strcmp(key,defs[i].key))return i;return -1;}
